sections.code:
// ── BEFORE: naive approach — multiple instances, diverging state ──
class Logger {
  constructor() {
    this._logs = [];
  }
  log(msg) { this._logs.push({ ts: Date.now(), msg }); }
  dump() { return this._logs; }
}

const loggerInModuleA = new Logger();
const loggerInModuleB = new Logger();

loggerInModuleA.log('App started');
loggerInModuleB.log('User logged in');

// Monitoring reads from whichever instance it has:
console.log(loggerInModuleA.dump().length); // 1 — only sees its own log
console.log(loggerInModuleB.dump().length); // 1 — different buffer!
// They are completely isolated. State is split across two objects.


// ── AFTER: class-based Singleton — shared state, one instance ────
class SingletonLogger {
  static #instance = null;

  #logs = [];

  constructor() {
    if (SingletonLogger.#instance) {
      throw new Error('Use SingletonLogger.getInstance() — do not call new directly');
    }
    SingletonLogger.#instance = this;
  }

  static getInstance() {
    if (!SingletonLogger.#instance) {
      new SingletonLogger(); // constructor stores the instance
    }
    return SingletonLogger.#instance;
  }

  log(msg)   { this.#logs.push({ ts: Date.now(), msg }); }
  dump()     { return [...this.#logs]; }
  get count(){ return this.#logs.length; }
}

const logA = SingletonLogger.getInstance();
const logB = SingletonLogger.getInstance();

console.log(logA === logB); // true — exact same reference

logA.log('App started');
logB.log('User logged in');  // writing through a different reference...

console.log(logA.dump());   // [{msg:'App started',...},{msg:'User logged in',...}]
console.log(logA.count);    // 2 — both writes land in one buffer
console.log(logB.count);    // 2 — same object, same count

// Attempting to bypass getInstance:
try {
  const rogue = new SingletonLogger(); // throws!
} catch (e) {
  console.log(e.message); // 'Use SingletonLogger.getInstance()...'
}

// ── Module singleton: Prisma client (real-world Node.js pattern) ─
// prisma.js — evaluated once by Node's module system
import { PrismaClient } from '@prisma/client';

// Singleton: created once at module evaluation time
const prisma = new PrismaClient({
  log: process.env.NODE_ENV === 'development' ? ['query'] : [],
});

// In development with hot-reload (Next.js, ts-node-dev),
// the module system re-evaluates on each reload, creating a new client
// and exceeding the DB connection limit. The standard fix:
if (process.env.NODE_ENV !== 'production') {
  // Attach to global (not re-evaluated on hot reload)
  globalThis.__prisma ??= prisma;
}

export default process.env.NODE_ENV !== 'production'
  ? globalThis.__prisma
  : prisma;


// ── Lazy class-based Singleton: config with runtime params ───────
class AppConfig {
  static #instance = null;

  #settings;

  constructor(overrides = {}) {
    if (AppConfig.#instance) {
      throw new Error('AppConfig already initialised — use AppConfig.getInstance()');
    }
    this.#settings = {
      apiUrl:      process.env.API_URL ?? 'http://localhost:3000',
      timeout:     Number(process.env.TIMEOUT ?? 5000),
      maxRetries:  3,
      ...overrides,   // allow test-time overrides
    };
    Object.freeze(this.#settings);
    AppConfig.#instance = this;
  }

  static getInstance(overrides) {
    if (!AppConfig.#instance) {
      new AppConfig(overrides);
    }
    return AppConfig.#instance;
  }

  get(key) { return this.#settings[key]; }

  // Escape hatch for testing — resets the singleton
  static _resetForTests() {
    AppConfig.#instance = null;
  }
}

// First call — initialise with overrides
const cfg1 = AppConfig.getInstance({ timeout: 1000 });

// Subsequent calls — overrides argument is ignored (instance exists)
const cfg2 = AppConfig.getInstance({ timeout: 9999 });

console.log(cfg1 === cfg2);        // true
console.log(cfg1.get('timeout'));  // 1000 — first call's overrides win

